import { unstable_cache } from "next/cache";

export interface Post {
  id: string;
  title: string;
  content: string;
  createdAt: string;
}

// In-memory store for demo. Replace with a database for production.
const posts: Post[] = [
  {
    id: "1",
    title: "Welcome",
    content: "This is the first post.",
    createdAt: new Date().toISOString(),
  },
];

function getPostsFromStore(): Post[] {
  return [...posts].sort(
    (a, b) =>
      new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
  );
}

export function getPosts(): Post[] {
  return getPostsFromStore();
}

/**
 * Fetches posts with cache tag "posts" for on-demand invalidation.
 * Use updateTag('posts') in Server Actions after creating/updating posts.
 */
export async function getCachedPosts(): Promise<Post[]> {
  return unstable_cache(
    async () => getPostsFromStore(),
    ["posts"],
    { tags: ["posts"] }
  )();
}

export function createPost(title: string, content: string): Post {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    content,
    createdAt: new Date().toISOString(),
  };
  posts.push(post);
  return post;
}

