"use server";

import { updateTag } from "next/cache";
import { createPost as createPostInStore } from "@/lib/posts";

export async function createPost(formData: FormData) {
  const title = formData.get("title");
  const content = formData.get("content");

  if (typeof title !== "string" || typeof content !== "string") {
    throw new Error("Title and content are required");
  }

  createPostInStore(title.trim(), content.trim());

  // Immediately expires the cached data for "posts". The next request will wait
  // for fresh data rather than serving stale content, ensuring users see
  // their new post right away (read-your-own-writes).
  updateTag("posts");
}

