import { getCachedPosts } from "@/lib/posts";
import { createPost } from "./actions";

export default async function Home() {
  const posts = await getCachedPosts();

  return (
    <main style={{ maxWidth: 600, margin: "0 auto", padding: 24 }}>
      <h1>Posts</h1>

      <form action={createPost} style={{ marginBottom: 32 }}>
        <div style={{ marginBottom: 12 }}>
          <label htmlFor="title" style={{ display: "block", marginBottom: 4 }}>
            Title
          </label>
          <input
            id="title"
            name="title"
            type="text"
            required
            style={{ width: "100%", padding: 8 }}
          />
        </div>
        <div style={{ marginBottom: 12 }}>
          <label htmlFor="content" style={{ display: "block", marginBottom: 4 }}>
            Content
          </label>
          <textarea
            id="content"
            name="content"
            required
            rows={3}
            style={{ width: "100%", padding: 8 }}
          />
        </div>
        <button type="submit" style={{ padding: "8px 16px" }}>
          Create Post
        </button>
      </form>

      <ul style={{ listStyle: "none", padding: 0 }}>
        {posts.map((post) => (
          <li
            key={post.id}
            style={{
              padding: 16,
              marginBottom: 12,
              border: "1px solid #eee",
              borderRadius: 8,
            }}
          >
            <h3 style={{ margin: "0 0 8px" }}>{post.title}</h3>
            <p style={{ margin: 0, color: "#666" }}>{post.content}</p>
          </li>
        ))}
      </ul>
    </main>
  );
}

